  $('#support-request-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const result=await api('/api/support/requests',{method:'POST',body:{phone:field(form,'phone'),message:field(form,'message')}});const dlg=openDialog('Unterstützungscode',`<div class="stack"><div class="warning-box"><strong>Geben Sie diesen Code nur beim Rückruf weiter.</strong><br>Er ist 24 Stunden gültig und öffnet nach Einlösung einen höchstens zweistündigen Supportzugriff.</div><div class="support-code">${esc(result.support_code)}</div></div>`,`<button class="button primary" id="close-support-code" value="none">Verstanden</button>`);$('#close-support-code',dlg).addEventListener('click',e=>{e.preventDefault();closeDialog();route()})}catch(error){toast(error.message,true)}});
  $$('.revoke-support').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Diese Supportfreigabe sofort widerrufen?'))return;try{await api(`/api/support/requests/${button.dataset.id}`,{method:'DELETE',body:{}});route();toast('Supportfreigabe wurde widerrufen.')}catch(error){toast(error.message,true)}}));
