function chooseImportClassDialog(classes){
  if(!classes.length){toast('Ihrem Konto ist noch keine Klasse freigeschaltet.',true);return}
  const automaticOption=!state.user.is_owner?'<option value="auto">Klassen automatisch anlegen</option>':'';
  const initialExplanation=!state.user.is_owner?'Alle Zeilen benötigen eine Angabe in der Spalte „Klasse“. Noch nicht vorhandene Klassen werden automatisch angelegt.':'Im Supportzugriff kann ausschließlich in eine freigegebene vorhandene Klasse importiert werden.';
  const dlg=openDialog('Zugänge importieren',`<div class="stack"><label>Klassenbehandlung<select id="import-target-class">${automaticOption}${classes.map(klass=>`<option value="${klass.id}">${esc(klass.name)} als Standardklasse</option>`).join('')}</select></label><div class="info-box" id="import-class-explanation">${initialExplanation}</div></div>`,`<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="continue-class-import" value="none">Weiter</button>`);
  const classSelect=$('#import-target-class',dlg),explanation=$('#import-class-explanation',dlg);
  classSelect.addEventListener('change',()=>{explanation.textContent=classSelect.value==='auto'?'Alle Zeilen benötigen eine Angabe in der Spalte „Klasse“. Noch nicht vorhandene Klassen werden automatisch angelegt.':'Die ausgewählte Klasse wird verwendet, wenn eine Zeile keine Klassenangabe enthält. Angaben in der Spalte „Klasse“ dürfen nur auf ebenfalls freigegebene Klassen verweisen.'});
  $('#continue-class-import',dlg).addEventListener('click',event=>{event.preventDefault();const classId=classSelect.value==='auto'?null:Number(classSelect.value);closeDialog();openImportDialog(classId)});
}
function openImportDialog(classId){importDialog(classId);const templateUrl=classId===null?'/api/users/import-template':`/api/classes/${classId}/template`;$('#dialog-body .stack',$('#dialog')).insertAdjacentHTML('afterbegin',`<div><a class="button" href="${templateUrl}">Importvorlage herunterladen</a></div>`)}
function userContextDialog(user){openDialog(`Zugang finden · ${user.first_name}`,`<div class="stack"><div class="account-identity"><span><strong>${esc(user.username)}</strong><small>${esc(user.class_name)} · letzte Anmeldung: ${fmt(user.last_login_at)}</small></span>${concealedCode(user.access_code)}</div><section class="user-context-projects"><h3>Aktuelle Projekte und Teams</h3>${user.projects.length?user.projects.map(project=>`<div class="context-project-row"><strong>${esc(project.title)}</strong><small>${user.teams.filter(team=>team.project_title===project.title).map(team=>`${esc(team.name)}${team.is_lead?' · Teamleitung':''}`).join(' · ')||'Keinem Team zugeordnet'}</small></div>`).join(''):empty('Noch kein Arbeitskontext','Dieser Zugang wurde noch keinem laufenden Projekt zugeordnet.')}</section><div class="info-box">Offene zugewiesene Aufgaben: <strong>${user.open_task_count}</strong></div></div>`,`<button class="button" value="cancel">Schließen</button>`);bindCodeToggles($('#dialog'))}
async function classMembershipDialog(klass,classes){
  try{
    const users=(await api(`/api/classes/${klass.id}/users`)).map(user=>({...user,class_id:klass.id,class_name:klass.name})).sort((a,b)=>a.first_name.localeCompare(b.first_name,'de'));
    const dlg=openDialog(`Klasse ${klass.name} bearbeiten`,`<div class="stack"><label>Klassenbezeichnung<input id="edit-class-name" value="${esc(klass.name)}" maxlength="30"><small class="muted">2 bis 30 Zeichen, ohne Leerzeichen.</small></label><div class="info-box">Hier werden ausschließlich die Zugänge dieser Klasse angezeigt. Über das Auswahlfeld können Sie einzelne Personen aus dieser Klasse in eine andere für Sie freigeschaltete Klasse verschieben. Projektmitgliedschaften werden dadurch nicht rückwirkend verändert.</div><div class="membership-list">${users.length?users.map(user=>`<div class="membership-row"><span><strong>${esc(user.first_name)}</strong><small>${esc(user.username)}</small></span><select data-user-id="${user.id}" data-original-class="${user.class_id}" aria-label="Klasse von ${esc(user.first_name)}">${classes.map(item=>`<option value="${item.id}" ${item.id===user.class_id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div>`).join(''):empty('Keine Zugänge','Dieser Klasse sind aktuell keine Lernenden zugeordnet.')}</div></div>`,`<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-class-memberships" value="none">Änderungen speichern</button>`);
    $('#save-class-memberships',dlg).addEventListener('click',async event=>{
      event.preventDefault();
      const className=$('#edit-class-name',dlg).value.trim(),nameChanged=className!==klass.name;
      const changes=$$('select[data-user-id]',dlg).filter(select=>select.value!==select.dataset.originalClass);
      if(!className)return toast('Bitte geben Sie eine Klassenbezeichnung ein.',true);
      if(!nameChanged&&!changes.length){closeDialog();return toast('Es wurden keine Änderungen vorgenommen.')}
      if(changes.length&&!confirm(`${changes.length} ${changes.length===1?'Klassenzugehörigkeit':'Klassenzugehörigkeiten'} wirklich ändern?`))return;
      try{if(nameChanged)await api(`/api/classes/${klass.id}`,{method:'PATCH',body:{name:className}});for(const select of changes)await api(`/api/users/${select.dataset.userId}`,{method:'PATCH',body:{class_id:Number(select.value)}});closeDialog();route();toast('Klasse wurde aktualisiert.')}catch(error){toast(error.message,true)}
    });
  }catch(error){toast(error.message,true)}
}
function deleteClassDialog(klass){
  const dlg=openDialog(`Klasse ${klass.name} löschen`,`<div class="stack"><div class="warning-box"><strong>Die Klasse wird aus der Verwaltung entfernt.</strong><br>Klassen mit laufenden Projekten können erst gelöscht werden, nachdem diese Projekte beendet oder archiviert wurden.</div><p>Was soll mit den ${klass.user_count} zugehörigen ${klass.user_count===1?'Zugang':'Zugängen'} geschehen?</p></div>`,`<button class="button" value="cancel">Abbrechen</button><button class="button danger" id="delete-class-keep-users" value="none">Zugänge behalten</button><button class="button danger" id="delete-class-with-users" value="none">Klasse und Zugänge löschen</button>`);
  const remove=async deleteUsers=>{
    try{await api(`/api/classes/${klass.id}`,{method:'DELETE',body:{delete_users:deleteUsers}});closeDialog();route();toast(deleteUsers?'Klasse und Zugänge wurden gelöscht.':'Klasse wurde gelöscht; die Zugänge bleiben erhalten.')}catch(error){toast(error.message,true)}
  };
  $('#delete-class-keep-users',dlg).addEventListener('click',event=>{event.preventDefault();remove(false)});
  $('#delete-class-with-users',dlg).addEventListener('click',event=>{event.preventDefault();remove(true)});
}
function classDialog(){const dlg=openDialog('Klasse anlegen','<form id="class-form" class="stack"><label>Klassenbezeichnung<input name="name" placeholder="z. B. GH24" required aria-describedby="class-name-help class-name-error"></label><small id="class-name-help" class="muted">2 bis 30 Zeichen, ohne Leerzeichen.</small><div id="class-name-error" class="warning-box hidden" role="alert"></div></form>','<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-class" value="none">Klasse anlegen</button>');$('#save-class',dlg).addEventListener('click',async e=>{e.preventDefault();const form=$('#class-form',dlg),input=$('[name=name]',form),error=$('#class-name-error',form),name=input.value.trim();error.classList.add('hidden');if(!name){error.textContent='Die Klassenbezeichnung darf nicht leer sein.';error.classList.remove('hidden');input.focus();return}if(/\s/.test(name)){error.textContent='Klassenbezeichnungen dürfen keine Leerzeichen enthalten.';error.classList.remove('hidden');input.focus();return}try{const result=await api('/api/classes',{method:'POST',body:{name}});closeDialog();location.hash=`#/admin/${result.id}`}catch(err){error.textContent=err.message;error.classList.remove('hidden');input.focus()}})}
function renderOwnAccount(){
  breadcrumbs([{label:'Verwaltung',href:'#/admin'},{label:'Eigenes Konto'}]);
  $('#content').innerHTML=pageHeader('Eigenes Konto','Persönliche Anmeldedaten Ihres Lehrkraftkontos verwalten.')+adminViewTabs('account')+`<section class="card account-settings"><form id="own-account-form" class="stack"><label>Angezeigter Name<input name="first_name" value="${esc(state.user.first_name)}" maxlength="80" required></label><label>Benutzername<input name="username" value="${esc(state.user.username)}" maxlength="50" required></label><label>Neues Kennwort <span class="muted">(optional)</span><input name="new_password" type="password" minlength="10" maxlength="256" autocomplete="new-password"></label><label>Aktuelles Kennwort <span class="muted">(nur bei neuem Benutzernamen oder Kennwort erforderlich)</span><input name="current_password" type="password" maxlength="256" autocomplete="current-password"></label><div class="info-box">Eine reine Änderung des angezeigten Namens benötigt keine erneute Kennworteingabe.</div><div><button class="button primary" id="save-own-account" type="submit">Änderungen speichern</button></div></form></section>`;
  $('#own-account-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const result=await api('/api/account',{method:'PATCH',body:{first_name:field(form,'first_name'),username:field(form,'username'),new_password:field(form,'new_password'),current_password:field(form,'current_password')}});state.user={...state.user,...result.user};$('#current-name').textContent=state.user.first_name;form.elements.new_password.value='';form.elements.current_password.value='';toast('Das eigene Konto wurde aktualisiert.')}catch(error){toast(error.message,true)}});
}
function createUserDialog(classId,users=[]){
  const dlg=openDialog('Zugang manuell anlegen',`<form id="create-user-form" class="stack"><label>Vorname<input name="first_name" required maxlength="80" placeholder="z. B. Lena"></label><div id="duplicate-user-warning" class="warning-box hidden" role="alert"></div><label>Benutzername <span class="muted">(optional)</span><input name="username" maxlength="50" placeholder="Wird automatisch erzeugt"></label><div class="info-box">Den Zugangscode erzeugt ProjektKontor automatisch. Ein leerer Benutzername wird ebenfalls automatisch vergeben. Beide Zugangsdaten können später über „Bearbeiten“ geändert werden.</div></form>`,`<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-new-user" value="none">Zugang anlegen</button>`);
  const form=$('#create-user-form',dlg),nameInput=$('[name=first_name]',form),warning=$('#duplicate-user-warning',form),actions=$('#dialog-actions');
  const createAccount=async()=>{
    const first_name=field(form,'first_name')?.trim();
    try{const account=await api(`/api/classes/${classId}/users`,{method:'POST',body:{first_name,username:field(form,'username')?.trim()}});closeDialog();route();toast(`Zugang ${account.username} wurde angelegt.`)}catch(error){toast(error.message,true)}
  };
  const showStandardActions=()=>{
    warning.classList.add('hidden');
    actions.innerHTML='<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-new-user" value="none">Zugang anlegen</button>';
    $('#save-new-user',dlg).addEventListener('click',checkAndCreate);
  };
  const checkAndCreate=event=>{
    event.preventDefault();
    const first_name=field(form,'first_name')?.trim();
    if(!first_name){toast('Bitte geben Sie einen Vornamen ein.',true);nameInput.focus();return}
    const normalized=first_name.toLocaleLowerCase('de-DE');
    const matches=users.filter(account=>account.first_name.trim().toLocaleLowerCase('de-DE')===normalized);
    if(matches.length){
      warning.textContent=`${first_name} ist in dieser Klasse bereits vorhanden. Trotzdem anlegen?`;
      warning.classList.remove('hidden');
      actions.innerHTML='<button class="button" id="correct-duplicate-user" value="none">Korrektur</button><button class="button primary" id="confirm-duplicate-user" value="none">Ja</button>';
      $('#correct-duplicate-user',dlg).addEventListener('click',correctionEvent=>{correctionEvent.preventDefault();showStandardActions();nameInput.focus();nameInput.select()});
      $('#confirm-duplicate-user',dlg).addEventListener('click',confirmEvent=>{confirmEvent.preventDefault();createAccount()});
      return;
    }
    createAccount();
  };
  $('#save-new-user',dlg).addEventListener('click',checkAndCreate);
  nameInput.addEventListener('input',()=>{if($('#confirm-duplicate-user',dlg))showStandardActions()});
}
function importDialog(classId){
  const automaticClasses=classId===null;
  const importBase=automaticClasses?'/api/users/import':`/api/classes/${classId}/import`;
  const explanation=automaticClasses?'Jede Zeile muss eine Klasse enthalten; noch nicht vorhandene Klassen werden automatisch angelegt.':'Die ausgewählte Klasse ist der Standard. Angaben in der Spalte „Klasse“ haben Vorrang; noch nicht vorhandene Klassen werden automatisch angelegt.';
  const dlg=openDialog('Zugänge importieren',`<div class="stack"><div class="info-box"><strong>Der Import ergänzt neue Zugänge.</strong> ${explanation} Bestehende Konten werden nicht verändert.</div><label>Excel-Datei<input id="excel-file" type="file" accept=".xlsx"></label><div id="import-preview"></div></div>`,'<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="preview-import" value="none">Vorschau erstellen</button>');
  $('#preview-import',dlg).addEventListener('click',async event=>{
    event.preventDefault();
    const file=$('#excel-file').files[0];
    if(!file)return toast('Bitte wählen Sie eine Datei.',true);
    try{
      const result=await api(`${importBase}-preview`,{method:'POST',body:{file_base64:await fileBase64(file)}});
      const hasDuplicates=result.rows.some(row=>row.duplicate);
      const hasNewClasses=result.rows.some(row=>row.new_class&&!row.error);
      const preview=$('#import-preview');
      preview.innerHTML=`${hasDuplicates?'<div class="warning-box">Gleichnamige Zugänge sind markiert. Prüfen Sie bitte, ob es sich tatsächlich um verschiedene Personen handelt.</div>':''}${hasNewClasses?'<div class="info-box">Die markierten Klassen sind noch nicht vorhanden und werden beim Import angelegt.</div>':''}<div class="table-wrap"><table><tr><th>Vorname</th><th>Klasse</th><th>Benutzername</th><th>Zugangscode</th><th>Hinweis</th></tr>${result.rows.map(row=>{const notes=[];if(row.new_class&&!row.error)notes.push('Neue Klasse');if(row.duplicate)notes.push('Name bereits vorhanden');if(row.error)notes.push(row.error);return `<tr class="${row.duplicate?'duplicate-row':''}"><td>${esc(row.first_name)}</td><td>${esc(row.class_name||'–')}${row.new_class&&!row.error?' <span class="warning">(neu)</span>':''}</td><td>${esc(row.username||'–')}</td><td>${row.access_code?concealedCode(row.access_code):'–'}</td><td>${notes.length?`<span class="${row.error||row.duplicate?'warning':''}">${esc(notes.join(' · '))}</span>`:'–'}</td></tr>`}).join('')}</table></div>`;
      bindCodeToggles(preview);
      $('#dialog-actions').innerHTML='<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="confirm-import" value="none">Konten ergänzen</button>';
      $('#confirm-import').addEventListener('click',async confirmEvent=>{
        confirmEvent.preventDefault();
        if(hasDuplicates&&!confirm('Die markierten gleichnamigen Zugänge trotzdem importieren?'))return;
        try{
          const done=await api(importBase,{method:'POST',body:{rows:result.rows,confirm_duplicates:hasDuplicates}});
          closeDialog();
          route();
          const classNotice=done.created_classes.length?` Zusätzlich wurden folgende Klassen angelegt: ${done.created_classes.join(', ')}.`:'';
          toast(`${done.created.length} Konten wurden ergänzt.${classNotice}`);
        }catch(error){toast(error.message,true)}
      });
    }catch(error){toast(error.message,true)}
  });
}
function editUserDialog(u,classes,currentClassId){const dlg=openDialog('Zugang bearbeiten',`<form id="user-form" class="stack"><label>Vorname<input name="first_name" value="${esc(u.first_name)}"></label><label>Klasse<select name="class_id"><option value="" ${!currentClassId?'selected':''}>Ohne Klasse</option>${classes.map(klass=>`<option value="${klass.id}" ${klass.id===currentClassId?'selected':''}>${esc(klass.name)}</option>`).join('')}</select><small class="muted">Hier können Sie den Zugang in eine andere Klasse verschieben.</small></label><label>Benutzername<input name="username" value="${esc(u.username)}"></label><label>Zugangscode<span class="secret-input"><input type="password" name="access_code" value="${esc(u.access_code)}" autocomplete="off"><button type="button" id="toggle-edit-code" aria-label="Zugangscode anzeigen" title="Zugangscode anzeigen">👁</button></span></label></form>`,`<button class="button" value="cancel">Abbrechen</button><button class="button primary" id="save-user" value="none">Speichern</button>`);const codeInput=$('[name=access_code]',dlg),toggle=$('#toggle-edit-code',dlg);toggle.addEventListener('click',()=>{const reveal=codeInput.type==='password';codeInput.type=reveal?'text':'password';toggle.textContent=reveal?'◉':'👁';toggle.setAttribute('aria-label',reveal?'Zugangscode verbergen':'Zugangscode anzeigen');toggle.title=toggle.getAttribute('aria-label')});$('#save-user',dlg).addEventListener('click',async e=>{e.preventDefault();const f=$('#user-form',dlg),classValue=field(f,'class_id'),newClassId=classValue?Number(classValue):null;if(newClassId!==currentClassId&&!confirm('Diesen Zugang wirklich in die ausgewählte Klasse verschieben?'))return;try{await api(`/api/users/${u.id}`,{method:'PATCH',body:{first_name:field(f,'first_name'),class_id:newClassId,username:field(f,'username'),access_code:field(f,'access_code')}});closeDialog();route();toast(newClassId===currentClassId?'Zugang aktualisiert.':'Zugang wurde in die andere Klasse verschoben.')}catch(err){toast(err.message,true)}})}
async function deleteUserDirect(user){
  if(!confirm(`Zugang ${user.username} von ${user.first_name} sofort endgültig löschen?`))return;
  try{await api(`/api/users/${user.id}`,{method:'DELETE'});route();toast(`Zugang ${user.username} wurde gelöscht.`)}catch(error){toast(error.message,true)}
}
function batchDeleteUsersDialog(users){
  const dlg=openDialog('Mehrere Zugänge löschen',`<div class="stack"><div class="warning-box"><strong>Ausgewählte Zugänge werden sofort endgültig gelöscht.</strong><br>Wählen Sie nur die Konten aus, die Sie wirklich entfernen möchten.</div><label class="batch-select-all"><input type="checkbox" id="select-all-users"> Alle Zugänge auswählen</label><div class="batch-user-list">${users.map(user=>`<label class="batch-user-row"><input type="checkbox" name="delete-user-id" value="${user.id}"><span><strong>${esc(user.first_name)}</strong><small>${esc(user.username)}</small></span></label>`).join('')}</div></div>`,`<button class="button" value="cancel">Abbrechen</button><button class="button danger" id="confirm-batch-delete" value="none" disabled>Ausgewählte Zugänge löschen</button>`);
  const boxes=$$('input[name=delete-user-id]',dlg),selectAll=$('#select-all-users',dlg),confirmButton=$('#confirm-batch-delete',dlg);
  const updateSelection=()=>{const selected=boxes.filter(box=>box.checked);confirmButton.disabled=!selected.length;confirmButton.textContent=selected.length?`${selected.length} ${selected.length===1?'Zugang':'Zugänge'} löschen`:'Ausgewählte Zugänge löschen';selectAll.checked=selected.length===boxes.length;selectAll.indeterminate=selected.length>0&&selected.length<boxes.length};
  selectAll.addEventListener('change',()=>{boxes.forEach(box=>box.checked=selectAll.checked);updateSelection()});
  boxes.forEach(box=>box.addEventListener('change',updateSelection));
  confirmButton.addEventListener('click',async event=>{
    event.preventDefault();
    const selected=boxes.filter(box=>box.checked).map(box=>users.find(user=>user.id===Number(box.value)));
    if(!selected.length||!confirm(`${selected.length} ${selected.length===1?'ausgewählten Zugang':'ausgewählte Zugänge'} sofort endgültig löschen?`))return;
    confirmButton.disabled=true;
    try{for(const user of selected)await api(`/api/users/${user.id}`,{method:'DELETE'});closeDialog();route();toast(`${selected.length} ${selected.length===1?'Zugang wurde':'Zugänge wurden'} gelöscht.`)}catch(error){closeDialog();route();toast(`Das Löschen wurde unterbrochen: ${error.message}`,true)}
  });
}

boot().catch(err=>{console.error(err);$('#auth').classList.remove('hidden');toast('ProjektKontor konnte nicht geladen werden.',true)});
